const PAGES0={};SX.net_wrap=()=>{};
function wrapPages(){for(const k of Object.keys(EXT)){if(PAGES0[k])continue;const d=Object.getOwnPropertyDescriptor(window,'PAGES');const Pg=typeof PAGES!=='undefined'?PAGES:null;if(!Pg||!Pg[k])continue;PAGES0[k]=Pg[k];Pg[k]=(...a)=>{const base=PAGES0[k](...a);let pre='',post='';EXT[k].forEach(x=>{if(x.before)pre+=x.before();if(x.after)post+=x.after()});return pre+base+post};
  const A0=typeof AFTER!=='undefined'?AFTER[k]:null;if(typeof AFTER!=='undefined')AFTER[k]=()=>{A0&&A0();EXT[k].forEach(x=>x.mounted&&x.mounted())}}}
// ---------------------------------------------------------------- consent for AI analysis
const aiConsent=()=>new Promise(res=>{if(S.consent.ai_analysis)return res(true);const eng=SX.cfg&&SX.cfg.ai&&SX.cfg.ai.engine==='claude';
 SX.modal(`<h2>${P('Analyse with AI?')}</h2><p>${P('The document is sent to the DoKKo server to be read')}${eng?' '+P('and to the AI provider (Anthropic) for this one analysis'):''}. ${P('It is processed and discarded: only the summary comes back to this device, and the file itself is never stored on the server.')}</p>
 <ul class="sx-ul"><li>${P('Nothing is diagnosed. Results are phrased for a conversation with your doctor.')}</li><li>${P('You can switch this off any time in Family & Privacy → Consent.')}</li></ul>
 <label class="sx-ck" style="display:flex;gap:8px;align-items:flex-start;margin:10px 0"><input type="checkbox" id="aiok" style="width:auto;margin-top:3px"><span>${P('I understand and allow DoKKo to analyse my documents.')}</span></label>
 <div style="display:flex;gap:8px;justify-content:flex-end"><button class="btn s" data-sx="closeModal">${P('Not now')}</button><button class="btn p" id="aigo">${P('Allow and analyse')}</button></div>`,{label:'Consent'});
 $('#aigo').onclick=()=>{if(!$('#aiok').checked){toast(P('Please tick the box first'));return}S.consent.ai_analysis=true;SX.ledger('ai_analysis',true,'Allowed AI analysis of documents',SX.me().id);SX.save();SX.closeModal();res(true)};
 const w=document.querySelector('.sx-modal');w._onclose=()=>res(!!S.consent.ai_analysis)});
SX.act.aioff=()=>{S.consent.ai_analysis=false;SX.ledger('ai_analysis',false,'AI analysis switched off',SX.me().id);SX.save();render();toast(P('AI analysis is off'))};
