 const needsRx=S.cart.some(c=>{const sel=document.querySelector(`.sx-modal [data-sxc^="cartrx:"]`);return !!sel});if(needsRx&&!S.consent.pharmacy_rx){toast(P('Allow prescription sharing first'));return}
